insert into public.products (id, category_id, slug, name, description, base_price_minor, currency, status, customizable, metadata, sort_order) values
  ('406203ea-6765-580e-a822-5413bb7bde8b', 'b74f5a81-0c06-5683-a860-9b425b6f7894', 'imperial-jade-bloom-ring', 'Imperial Jade Bloom Ring', 'A breathtaking floral ring featuring an imperial jade cabochon surrounded by rose-cut diamonds. The petal design evokes eternal beauty and nature''s artistry.', 1280000, 'SGD', 'draft', true, '{"seedStatus":"provisional","nameCn":"帝王翡翠花戒指","descriptionCn":"令人惊叹的花卉戒指，以帝王翡翠蛋面配以玫瑰切割钻石。花瓣设计唤起永恒的美丽和自然的艺术。","materials":["18K White Gold","Platinum 950"],"occasions":["engagement","anniversary","self-love"],"featured":true}'::jsonb, 0),
