  ('0d3f3ffc-0845-52f4-a47d-62ff529f8875', 'b74f5a81-0c06-5683-a860-9b425b6f7894', 'celestial-diamond-floral-ring', 'Celestial Diamond Floral Ring', 'An oval brilliant diamond set in a golden prong setting, surrounded by a pavé diamond petal motif. Two-tone craftsmanship at its finest.', 980000, 'SGD', 'draft', true, '{"seedStatus":"provisional","nameCn":"天旋钻石花戒指","descriptionCn":"椭圆形明亮切割钻石镶嵌在金色爪座中，周围环绕密镶钻石花瓣图案。精湛的双色工艺。","materials":["18K Yellow Gold","18K White Gold"],"occasions":["engagement","proposal","anniversary"],"featured":true}'::jsonb, 2),
