  ('ed9130d8-4585-5e4f-a26a-a32828eb5f41', 'b74f5a81-0c06-5683-a860-9b425b6f7894', 'emerald-marquise-ring', 'Emerald Accent Marquise Ring', 'A striking marquise-cut diamond framed by emerald accents and pavé petals. Bold contrast meets floral elegance.', 1350000, 'SGD', 'draft', true, '{"seedStatus":"provisional","nameCn":"祖母绿点缀马眼形戒指","descriptionCn":"引人注目的马眼形切割钻石配以祖母绿点缀和密镶花瓣。大胆对比与花卉优雅相遇。","materials":["18K Yellow Gold","18K White Gold"],"occasions":["engagement","anniversary","self-love"],"featured":true}'::jsonb, 6),
