insert into public.translations (id, namespace, key, locale, value, status) values
  ('254831c2-277c-5fc2-a33a-6ab6b120ca45', 'product', 'imperial-jade-bloom-ring.name', 'zh-SG', '帝王翡翠花戒指', 'draft'),
  ('21b45daa-e1f0-50d6-a7ac-16d0b594ea5a', 'product', 'imperial-jade-bloom-ring.description', 'zh-SG', '令人惊叹的花卉戒指，以帝王翡翠蛋面配以玫瑰切割钻石。花瓣设计唤起永恒的美丽和自然的艺术。', 'draft'),
  ('9908eb6e-d685-53bf-a849-a28484bf5fe2', 'product', 'jade-cabochon-statement-ring.name', 'zh-SG', '翡翠蛋面豪华戒指', 'draft'),
  ('c3efe702-9c39-5bb0-a3ca-bbe7b62a12d8', 'product', 'jade-cabochon-statement-ring.description', 'zh-SG', '华丽的豪华戒指，璀璨的翡翠蛋面镶嵌在钻石花卉底座中。', 'draft'),
  ('cb1eb2cc-f5bb-57e3-a20e-4d26f910353b', 'product', 'celestial-diamond-floral-ring.name', 'zh-SG', '天旋钻石花戒指', 'draft'),
  ('86931552-2d0c-59b1-ac68-d077d0b6cf60', 'product', 'celestial-diamond-floral-ring.description', 'zh-SG', '椭圆形明亮切割钻石镶嵌在金色爪座中，周围环绕密镶钻石花瓣图案。精湛的双色工艺。', 'draft'),
  ('4de6192f-5228-55db-a6eb-64985e4fb0a9', 'product', 'cushion-brilliance-ring.name', 'zh-SG', '垫形璀璨戒指', 'draft'),
  ('c63442a1-5e21-5888-a319-6633f57ff197', 'product', 'cushion-brilliance-ring.description', 'zh-SG', '大方的垫形切割钻石镶嵌在金色螺旋底座中，密镶钻石花瓣创造出难忘的轮廓。', 'draft'),
  ('d8024165-7cf7-5583-ade1-49adf650f633', 'product', 'radiant-solitaire-ring.name', 'zh-SG', '雷电单石戒指', 'draft'),
  ('b55fea2b-2273-5c4a-af8a-35e3f2534216', 'product', 'radiant-solitaire-ring.description', 'zh-SG', '明亮的垫形切割钻石镶嵌在白金花卉底座中。简洁、永恒、绝对耀眼。', 'draft'),
  ('11f19613-2229-53c0-ad46-db845ec63798', 'product', 'noble-round-brilliant-ring.name', 'zh-SG', '贵族圆形明亮戒指', 'draft'),
  ('4b406bd1-239c-5989-aeb3-2fe41689ef10', 'product', 'noble-round-brilliant-ring.description', 'zh-SG', '华丽的圆形明亮切割钻石围绕光环镶钻石。全铂金底座展现低调的华丽。', 'draft'),
  ('6786ff1d-1357-5920-a7b8-ecebf9e76886', 'product', 'emerald-marquise-ring.name', 'zh-SG', '祖母绿点缀马眼形戒指', 'draft'),
  ('9f2f9d75-8fc2-57bd-a28f-92886fa03a16', 'product', 'emerald-marquise-ring.description', 'zh-SG', '引人注目的马眼形切割钻石配以祖母绿点缀和密镶花瓣。大胆对比与花卉优雅相遇。', 'draft'),
  ('ed11e0a9-b127-5430-abcb-dd91cf5ce99d', 'product', 'vintage-petal-ring.name', 'zh-SG', '复古花瓣戒指', 'draft'),
  ('af901867-844e-568c-a781-dea612d1efde', 'product', 'vintage-petal-ring.description', 'zh-SG', '精致的多层花瓣图案戒指，搭配突出的中心宝石。复古魅力与现代光彩并存。', 'draft'),
