  ('7af27f79-62fa-5092-a36f-3c7a14ffda7b', 'product', 'jade-stud-earrings.name', 'zh-SG', '翡翠蛋面耳钉', 'draft'),
  ('44cd6ecb-a1f6-5ed8-a150-0bb4363dbfaf', 'product', 'jade-stud-earrings.description', 'zh-SG', '精致的翡翠蛋面镶嵌在金色包镶中。日常优雅的低调绿意。', 'draft'),
  ('6dcb0484-947f-5f3f-a258-c621aaccd09c', 'product', 'jade-drop-earrings.name', 'zh-SG', '翡翠耳坠', 'draft'),
